export type PortalLocale = 'en' | 'fa' | 'ps' | 'ru' | 'tr' | 'de' | 'fr' | 'ar' | 'ur';

export const isRtlPortal = (locale: string): boolean => {
  return ['fa', 'ps', 'ar', 'ur'].includes(locale);
};

export const getPortalTranslation = (locale?: string) => {
  const loc = (locale && locale in portalTranslations ? locale : 'en') as PortalLocale;
  return portalTranslations[loc] || portalTranslations.en;
};

